local P={}
local function finite(v)return type(v)=='number'and v==v and math.abs(v)<math.huge end
function P.terrain(input,atlas,C)
 local p=profiles[input.mapId]
 if not p or input.pair~=p.pair or input.width~=p.width or input.height~=p.height or C.ELEV_UNIT~=.25 or C.ROCK_KERB_H~=.35 or atlas.w~=256 or atlas.h~=p.atlasH then return nil end
 if p.waterCells and C.WATER_DEPTH~=.15 then return nil end
