 for y=0,p.height-1 do for x=0,p.width-1 do
  local c=input.cellAt(x,y);local n=p.types[p.rows[y+1][x+1]]
  if not c or c.mid~=n[1]or c.collision~=n[2]or c.elevation~=n[3]or c.behavior~=(n[4]~=-1 and n[4]or nil)or c.layerType~=n[5]or c.walkable~=(n[6]==1)or c.category~=n[8]then return nil end
 end end
 if p.borderChecks then
  if C.ROCK_H0~=1 or C.ROCK_STEP~=.5 or C.ROCK_MAX_H~=1.5 or C.ROCK_LUMP_H~=.7 or C.CLIFF_REJOIN~=true then return nil end
  for _,name in ipairs{'texels','underRect','overRect','hasOver','overCoverage'}do if type(atlas[name])~='function'then return nil end end
  if C.WATER_DEPTH~=.15 or type(input.nativeTerrainBorderAt)~='function' then return nil end
  for _,xy in ipairs(p.borderChecks)do
   local ok,c=pcall(input.nativeTerrainBorderAt,xy[1],xy[2])
   if not ok or type(c)~='table' or c.mid~=473 or c.collision~=7 or c.elevation~=0 or c.behavior~=21 or c.layerType~=1 or c.walkable~=false or c.category~='BLOCKED' then return nil end
  end
 end
 for mid,a in pairs(p.art)do
  if atlas.hasOver(mid)~=(a.coverage>0)or atlas.overCoverage(mid)~=a.coverage then return nil end
  for li,layer in ipairs{'under','over'}do
   local t=atlas.texels(mid,layer);local h=-2
   if t then h=0;for i=1,256 do if not finite(t[i])then return nil end;h=(h*33+t[i]+2)%4294967291 end end
   if h~=a.hashes[li]then return nil end
