  local edges={{46,-1},{47,-1},{48,-1},{49,-1},{50,-1},{51,-1},{52,-1},{53,-1},{54,-1},{55,-1},{56,-1},{57,-1},{58,-1},{59,-1},{60,-1},{61,-1},{62,-1},{63,-1},{64,-1},{65,-1},{66,-1},{67,-1},{68,-1},{69,-1},{70,-1},{71,-1},{72,-1},{73,-1},{74,-1},{75,-1},{76,-1},{77,-1},{78,-1},{79,-1},{80,-1},{81,-1},{82,-1},{83,-1},{84,-1},{85,-1},{86,-1},{87,-1},{64,20},{65,20},{66,20},{67,20},{68,20},{69,20},{70,20},{71,20},{72,20},{73,20},{74,20},{75,20},{76,20},{77,20},{78,20},{79,20},{80,20},{81,20},{82,20},{83,20},{84,20},{85,20}}
